	// thread. For a fixed (r,s) we still accumulate over t in order
	// t = 0..n-1, so the numerical result is bit-identical to the original
	// t–r–s loop nest.
	auto trav_all = traverser(B_rst, A_rt, A_st).order(hoist<'r'>());

	#pragma omp parallel for
	for (auto trav_r : trav_all) {
		trav_r.for_each([&](auto state) {
			B_rst[state] += A_rt[state] * A_st[state];
		});
	}

	// Copy B back into A: A[r][s] = B[r][s]
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
