[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension (matrix is n x n)
	const std::size_t n = A | get_length<'i'>();

	// Reusable reference bag for cheap view construction
	auto A_ref = A.get_ref();

	// ------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// Rewritten with a Noarr traverser over the (i,j) grid and an explicit
	// inner k-loop. For each row i we build a row view so A[i][k] stays
	// unit‑stride in memory.

	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// View of row i: only 'j' remains as a dimension.
		auto row_i = A_ref ^ fix<'i'>(i_idx);

		trav_i.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);

			num_t w = row_i.template at<'j'>(j_idx);

			const std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;
			for (std::size_t k = 0; k < max_k; ++k) {
				w -= row_i.template at<'j'>(k) *
				     A_ref.template at<'i', 'j'>(k, j_idx);
			}

			if (j_idx < i_idx) {
				w /= A_ref.template at<'i', 'j'>(j_idx, j_idx);
			}

			// Write back through the row view (updates A as well).
			row_i.template at<'j'>(j_idx) = w;
		});
	});

	// ------------------------------------------------------------------
	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }

	traverser(A, y, b).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b[s_i];

		trav_i.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);
			if (j_idx < i_idx) {
				w -= A_ref.template at<'i', 'j'>(i_idx, j_idx) *
				     y.template at<'i'>(j_idx);
			}
		});

		y[s_i] = w;
	});

	// ------------------------------------------------------------------
	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// Implemented with an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv

	traverser(A, x, y).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		const std::size_t inv = get_index<'i'>(s_inv);
		const std::size_t i_idx = n - 1 - inv;

		num_t w = y.template at<'i'>(i_idx);

		trav_inv.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);
			if (j_idx > i_idx) {
				w -= A_ref.template at<'i', 'j'>(i_idx, j_idx) *
				     x.template at<'i'>(j_idx);
			}
		});

		x.template at<'i'>(i_idx) =
			w / A_ref.template at<'i', 'j'>(i_idx, i_idx);
	});
}

