		const std::size_t i = get_index<'i'>(s_i);
		const std::size_t n_sz = static_cast<std::size_t>(n);

		// Lower triangle: j in [0, i)
		if (i > 0) {
			auto trav_lower = trav_i.order(slice<'j'>(0, i));
			trav_lower.for_each([&](auto state) {
				auto j = get_index<'j'>(state);

				int rem = (-static_cast<int>(j)) % n;
				A[state] = static_cast<num_t>(rem) * inv_n + num_t(1);
			});
		}

		// Diagonal element j == i
		if (i < n_sz) {
			auto trav_diag = trav_i.order(slice<'j'>(i, 1));
			trav_diag.for_each([&](auto state) {
				A[state] = num_t(1);
			});
		}

		// Upper triangle: j in (i, n)
		if (i + 1 < n_sz) {
			auto trav_upper =
				trav_i.order(slice<'j'>(i + 1, n_sz - i - 1));
			trav_upper.for_each([&](auto state) {
				A[state] = num_t(0);
			});
		}
	});

	// Make the matrix positive semi-definite:
	//
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]
	//
	// B has the same structure as A.
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ rename<'i', 'r', 'j', 's'>();

	// Accumulate B[r][s] += A[r][t] * A[s][t].
	//
	// We iterate 't' explicitly with for_dims<'t'>, yielding
	//   for (t ...)
	//     for (r ...)
	//       for (s ...)
	//         B[r][s] += A[r][t] * A[s][t];
	//
	// B_rs ignores the extra 't' index present in the state, so we do
	// not need an explicit broadcast proto-structure here.
	traverser(A_rt, A_st, B_rs)
		.template for_dims<'t'>([&](auto trav_t) {
			trav_t.for_each([&](auto state) {
				B_rs[state] += A_rt[state] * A_st[state];
			});
		});

	// Copy B back into A: A[r][s] = B[r][s]
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
