// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Matrix dimension in the 'i' direction (n x n)
	const std::size_t n = A | get_length<'i'>();

	// LU factorization (Doolittle-like scheme)
	//
	// Textbook row-wise algorithm:
	// for (i = 0; i < N; i++) {
	//   // Compute L(i,0..i-1)
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//
	//   // Compute U(i,i..N-1)
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We express the outer i-loop via for_dims<'i'> and then implement
	// the j< i and j >= i ranges as two separate Noarr traversals for
	// better branch-free inner loops and improved data locality.

	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i = get_index<'i'>(s_i);

		// 1D view of row i: all accesses A[i][j] become row_i[...].
		auto row_i = A ^ fix<'i'>(i);

		// ----- Lower part: j in [0, i) -----
		if (i > 0) {
			auto trav_lower = trav_i.order(slice<'j'>(0, i));
			trav_lower.for_each([&](auto state) {
				const std::size_t j = get_index<'j'>(state);

				num_t w = row_i[state]; // A[i][j]

				// max_k == j here
				for (std::size_t k = 0; k < j; ++k) {
					w -= A[noarr::idx<'i', 'j'>(i, k)] *
					     A[noarr::idx<'i', 'j'>(k, j)];
				}

				// L(i,j) = w / A[j][j]
				w /= A[noarr::idx<'i', 'j'>(j, j)];
				row_i[state] = w;
			});
		}

		// ----- Upper part (including diagonal): j in [i, n) -----
		auto trav_upper = trav_i.order(slice<'j'>(i, n - i));
		trav_upper.for_each([&](auto state) {
			const std::size_t j = get_index<'j'>(state);

			num_t w = row_i[state]; // A[i][j]

			// max_k == i here
			for (std::size_t k = 0; k < i; ++k) {
				w -= A[noarr::idx<'i', 'j'>(i, k)] *
				     A[noarr::idx<'i', 'j'>(k, j)];
			}

			// U(i,j) = w  (diagonal included)
			row_i[state] = w;
		});
	});

	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We iterate i with for_dims<'i'> and restrict the inner traversal
	// of 'j' to [0, i) using a sliced order, avoiding an inner branch.
	traverser(y, b, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i = get_index<'i'>(s_i);

		num_t w = b[s_i];

		if (i > 0) {
			auto trav_j = trav_i.order(slice<'j'>(0, i));
			trav_j.for_each([&](auto state) {
				const std::size_t j = get_index<'j'>(state);

				w -= A[noarr::idx<'i', 'j'>(i, j)] *
				     y[noarr::idx<'i'>(j)];
			});
		}

		y[s_i] = w;
	});

	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We keep the physical traversal of 'i' ascending (0..n-1) to
	// preserve locality and map each logical index as i = N-1-inv.
	// For each i we traverse only j in (i, N) via a sliced view.
	traverser(x, y, A).template for_dims<'i'>([&](auto trav_i) {
		auto s_inv = trav_i.state();
		const std::size_t inv = get_index<'i'>(s_inv);
		const std::size_t i = n - 1 - inv;

		num_t w = y[noarr::idx<'i'>(i)];

		if (i + 1 < n) {
			auto trav_j = trav_i.order(slice<'j'>(i + 1, n - (i + 1)));
			trav_j.for_each([&](auto state) {
				const std::size_t j = get_index<'j'>(state);

				w -= A[noarr::idx<'i', 'j'>(i, j)] *
				     x[noarr::idx<'i'>(j)];
			});
		}

		x[noarr::idx<'i'>(i)] =
			w / A[noarr::idx<'i', 'j'>(i, i)];
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
