	// identical with the scalar triple loop.
	// -----------------------------------------------------------------

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Create views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();
	// B_rst: B[r][s] broadcast over t
	auto B_rst = B_rs ^ noarr::bcast<'t'>(n);

	// Block (r,s) for better cache locality. We use into_blocks_static
	// which logically splits each dimension into body+border parts and
	// then into (block index, index within block). This preserves the
	// original set of (r,s) coordinates and their per-element update
	// order in t, but iterates them in cache-friendly tiles.
	const std::size_t blk = tuning.spd_block;
	auto blocking =
		noarr::into_blocks_static<'r', 'p', 'R', 'r'>(blk) ^ // 'p' distinguishes body/border in r
		noarr::into_blocks_static<'s', 'q', 'S', 's'>(blk);  // 'q' distinguishes body/border in s

	noarr::traverser(B_rst, A_rt, A_st)
		// t is hoisted as the outermost loop: for each t, we walk all (r,s)
		.order(noarr::hoist<'t'>() ^ blocking)
		.for_each([&](auto state) {
			// state contains t, R/S (block indices), p/q (body/border flags),
			// and r/s (indices within a block); the views take care of mapping
			// these back to the correct r,s coordinates.
			B_rst[state] += A_rt[state] * A_st[state];
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Length in the 'i' dimension
	std::size_t n = A | get_length<'i'>();

	// Create non-owning reference bags (makes the intent explicit).
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// 1D helper views used in the forward/backward substitution phases:
	// rename 'i' -> 'k' so that we can zip vectors along a common dimension.
	auto x_as_k = x_ref ^ rename<'i', 'k'>(); // x[k]
	auto y_as_k = y_ref ^ rename<'i', 'k'>(); // y[k]

	// =================================================================
	// 1) LU factorization (Doolittle-like scheme, in-place in A)
	//
	// Original scalar algorithm:
	//
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We implement an equivalent form where the inner k-loop is expressed
	// as a 1D traverser over a "row as vector" and a "column as vector",
	// zipped over a common reduction dimension 'k'. The k indices are
	// still visited in ascending order, so each scalar dot-product keeps
	// the exact same floating‑point order.
	// =================================================================
	traverser(A_ref).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has dimension 'i' fixed to some i_idx, remaining dim 'j'
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// View of the i-th row A[i, *], exposing the column index as
		// dimension 'k' so we can reuse it in several dot-products.
		auto row_i_k = A_ref ^ fix<'i'>(i_idx) ^ rename<'j', 'k'>(); // A[i][k]

		trav_i.for_each([&](auto s_ij) {
			std::size_t j_idx = get_index<'j'>(s_ij);

			// Start from the stored value A[i][j]
			num_t w = A_ref[s_ij];

			// Upper limit for the dot-product:
			//   max_k = (j < i ? j : i)
			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			if (max_k > 0) {
				// View of the j-th column A[*, j], again as a 1D structure in 'k'
				// (we rename 'i' -> 'k', so row_i_k and col_j_k share the same
				// logical dimension for zipping).
				auto col_j_k = A_ref ^ fix<'j'>(j_idx) ^ rename<'i', 'k'>(); // A[k][j]

				// Dot product: sum_{k=0..max_k-1} A[i][k] * A[k][j]
				// realized as a 1D traversal over 'k' with a slice [0, max_k).
				traverser(row_i_k, col_j_k)
					.order(slice<'k'>(0, max_k))
					.for_each([&](auto s_k) {
						w -= row_i_k[s_k] * col_j_k[s_k];
					});
			}

			if (j_idx < i_idx) {
				// Below diagonal: store L(i,j) = w / A[j][j]
				auto s_jj = idx<'i', 'j'>(j_idx, j_idx);
				A_ref[s_ij] = w / A_ref[s_jj];
			} else {
				// On / above diagonal: U(i,j) = w
				A_ref[s_ij] = w;
			}
		});
	});

	// =================================================================
	// 2) Forward substitution: solve L * y = b
	//
	// Scalar version:
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// Here, the inner sum is again expressed as a 1D traversal over the
	// first i elements of row i (dimension 'k') and the first i elements
	// of vector y (also dimension 'k').
	// =================================================================
	traverser(y_ref, b_ref, A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b_ref[s_i];

		if (i_idx > 0) {
			// Row i of L (only the first i entries are used):
			auto row_i_k = A_ref ^ fix<'i'>(i_idx) ^ rename<'j', 'k'>(); // A[i][k]

			// Zip row_i_k[0..i-1] with y_as_k[0..i-1]
			traverser(row_i_k, y_as_k)
				.order(slice<'k'>(0, i_idx))
				.for_each([&](auto s_k) {
					w -= row_i_k[s_k] * y_as_k[s_k];
				});
		}

		y_ref[s_i] = w;
	});

	// =================================================================
	// 3) Backward substitution: solve U * x = y
	//
	// Scalar version:
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We traverse i in ascending order using an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	// and again express the inner sum as a 1D traversal over a tail of
	// row i (dimension 'k') zipped with the corresponding tail of x.
	// =================================================================
	traverser(x_ref, y_ref, A_ref).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv; // map inv -> i

		auto s_i = idx<'i'>(i_idx);
		num_t w = y_ref[s_i];

		if (i_idx + 1 < n) {
			// Row i of U: elements j in (i+1 .. n-1) become k in (i+1 .. n-1)
			auto row_i_k = A_ref ^ fix<'i'>(i_idx) ^ rename<'j', 'k'>(); // A[i][k]

			std::size_t start = i_idx + 1;
			std::size_t len = n - start;

			auto row_tail = row_i_k ^ slice<'k'>(start, len);
			auto x_tail   = x_as_k  ^ slice<'k'>(start, len);

			traverser(row_tail, x_tail).for_each([&](auto s_k) {
				w -= row_tail[s_k] * x_tail[s_k];
			});
		}

		auto s_ii = idx<'i', 'j'>(i_idx, i_idx);
		x_ref[s_i] = w / A_ref[s_ii];
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structures and bags
	auto set_len_i = noarr::set_length<'i'>(n);
	auto set_len_ij = set_len_i ^ noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len_ij);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout ^ set_len_i);

	// Initialize data
	init_array(static_cast<int>(n),
	           A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_ludcmp(A.get_ref(), b.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Output result to stderr (for DCE / checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// Output timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
